SELECT EXISTS (
SELECT 1
FROM potential_customer
WHERE id = #{customerId}
)

SELECT EXISTS (
SELECT 1
FROM integrated_customer
WHERE integrated_customer_id = #{customerId}
)

SELECT COUNT(*)
FROM potential_customer
WHERE id = #{customerId}
AND sales_user_id = #{salesUserId}

SELECT COUNT(*)
FROM integrated_customer
WHERE integrated_customer_id = #{customerId}
AND sales_user_id = #{salesUserId}

SELECT COUNT(*)
FROM potential_customer
WHERE id = #{customerId}
AND sales_user_id = #{salesUserId}

SELECT target_category_code AS categoryCode, SUM(weight_score) AS score FROM question_mapping WHERE option_value IN
#{answer}
GROUP BY target_category_code

SELECT id AS coverageId, category_code AS categoryCode, coverage_name AS coverageName, unit_premium AS unitPremium, danger_priority_order AS dangerPriorityOrder FROM insurance_coverage WHERE category_code IN
#{code}
AND #{age} BETWEEN min_target_age AND max_target_age

SELECT
data_year AS dataYear,
rank_by_age_gender AS rankByAgeGender
FROM cdc_disease_statistic
WHERE target_coverage_id = #{coverageId}
AND age_group_code = #{ageGroupCode}
AND gender = #{gender}
ORDER BY data_year DESC
